import{z as E,x as p,o as r,c,q as o,j as l,D as t,d as a,s as n,S as d,b as s}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"顺序统计树","description":"","frontmatter":{"title":"顺序统计树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/order-statistic-tree.md","filePath":"cs/order-statistic-tree.md","lastUpdated":1791413859000}'),B={name:"cs/order-statistic-tree.md"};function A(m,e,k,h,C,u){const i=p("Mermaid");return r(),c("div",null,[e[2]||(e[2]=o('<h1 id="顺序统计树" tabindex="-1">顺序统计树 <a class="header-anchor" href="#顺序统计树" aria-label="Permalink to &quot;顺序统计树&quot;">​</a></h1><div class="epigraph"><p>每个节点多记一棵子树的规模，秩就是左子树大小加一；第 $k$ 小沿这条计数往下走。</p><footer>—— 据 Cormen, Leiserson, Rivest and Stein, Introduction to Algorithms 第 14 章；Sedgewick and Wayne 整理</footer></div><p><a href="/cs/splay-tree">上一课</a>与<a href="/cs/rbtree-intuition">红黑</a>、<a href="/cs/treap">Treap</a> 都给了有序字典，但合同只有按键。需要「第 \\(k\\) 小的键」或「小于 \\(x\\) 的有多少」。本课不重做 splay 势能。缺口是顺序统计树：在平衡 BST 上维护 <code>size</code>，<code>select</code>/<code>rank</code> 与增删同阶对数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有序数组 <code>select</code> 是下标，但插入 \\(\\Theta(n)\\)。只存 BST 没有规模就不能在比较路径上跳过「左边有多少」。缺口是字段 \\(\\mathrm{size}(u)=1+\\mathrm{size}(左)+\\mathrm{size}(右)\\)（空为 0）。\\(\\mathrm{rank}(x)\\)：走查找路径，往右走时加上左子树 size 再加一。\\(\\mathrm{select}(k)\\)：若 \\(k=\\mathrm{size}(左)+1\\) 则根，若更小则向左，否则向右减掉左边与根。</p><p>旋转、splay、treap 的 split 都必须更新 size，与维护平衡同一路径。</p><p><span class="marginnote">CLRS 第 14 章用红黑当底层。底层换成 AVL/Treap/Splay 只改维护点，不改秩的定义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>插入删除先当普通 BST 再修复平衡，回溯加/减 size，或旋转时按公式重算四个节点。区间 \\([L,R]\\) 内第 \\(k\\) 小：两个前缀版本的 rank 相减消去左端前缀，得区间内 \\(\\le x\\) 的计数，按计数定位第 \\(k\\) 小——这是应用，机制仍是全局序上的秩。</p><p><span class="marginnote">术语翻译：<code>select(k)</code> 是「按名次找人」——报出第 \\(k\\) 名是谁；<code>rank(x)</code> 是「按人报名次」——问 \\(x\\) 排第几。有序数组天然会这两件事，但插入要整体搬动；顺序统计树给每个节点多记一个「我这边管多少节点」的计数，就把两问都变成走一条路径。</span></p><p><span class="marginnote">直觉类比：size 像每个部门墙上挂的「在册人数」牌。旋转只是两个部门换了上下级，总人数没变，但两块牌子要按新辖区重写——先重算下属、再重算自己；顺序错了就拿旧数算新数，整棵账全歪。</span></p>',11)),(r(),l(d,null,{default:t(()=>[n(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22select%20k%22%5D%20--%3E%20LSIZE%5B%22s%20%3D%20size(%E5%B7%A6)%22%5D%0A%20%20LSIZE%20--%3E%20EQ%5B%22k%20%3D%20s%2B1%3A%20%E6%A0%B9%22%5D%0A%20%20LSIZE%20--%3E%20LEFT%5B%22k%20%EF%BC%9C%3D%20s%3A%20%E5%B7%A6%22%5D%0A%20%20LSIZE%20--%3E%20RIGHT%5B%22k%20%3E%20s%2B1%3A%20%E5%8F%B3%2C%20k%20-%3D%20s%2B1%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=s("p",null,"与 Fenwick 权值树：值域离散且可映射到下标时，树状数组也能 rank/select。顺序统计树键任意可比较，不必整数化。",-1)),e[4]||(e[4]=s("h2",{id:"机制",tabindex:"-1"},[a("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=s("p",null,[a("平衡保证 \\(h=O(\\log n)\\)，故 rank/select 最坏或期望对数与底层一致。size 错一个节点，经过它的秩全错——测试应查 "),s("code",null,"size"),a(" 与中序位置。多重键：size 计次数或拆节点，合同写明。")],-1)),(r(),l(d,null,{default:t(()=>[n(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20START%5B%22rank%20x%3A%20%E4%BB%8E%E6%A0%B9%E5%87%BA%E5%8F%91%2C%20r%20%3D%200%22%5D%20--%3E%20CMP%7B%22x%20%E4%B8%8E%E5%BD%93%E5%89%8D%E8%8A%82%E7%82%B9%E9%94%AE%E6%AF%94%E8%BE%83%22%7D%0A%20%20CMP%20--%3E%7C%22%E7%9B%B8%E7%AD%89%22%7C%20ANS%5B%22r%20%E5%8A%A0%E4%B8%8A%20size(%E5%B7%A6)%20%E5%8A%A0%201%2C%20%E8%BF%94%E5%9B%9E%22%5D%0A%20%20CMP%20--%3E%7C%22x%20%E6%9B%B4%E5%B0%8F%22%7C%20GO%5B%22%E5%90%91%E5%B7%A6%E8%B5%B0%2C%20r%20%E4%B8%8D%E5%8F%98%22%5D%0A%20%20CMP%20--%3E%7C%22x%20%E6%9B%B4%E5%A4%A7%22%7C%20ADD%5B%22r%20%E5%8A%A0%E4%B8%8A%20size(%E5%B7%A6)%20%E5%8A%A0%201%2C%20%E5%90%91%E5%8F%B3%E8%B5%B0%22%5D%0A%20%20GO%20--%3E%20CMP%0A%20%20ADD%20--%3E%20CMP%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=o('<p><span class="marginnote">数字实例：一棵 7 节点的满树，若根的左孩子 size 被记成 2（漏了一个），凡查询落在根自己或右子树的键上都要读这个左孩子计数，rank 统一被压小 1——真实的第 7 名会被报成第 6 名，而左子树内部的秩不受影响。所以测试要在每次增删旋转后逐节点核对 size 与中序位置：一个节点的账错了，路过它的名次都错。</span></p><p>不要把「第 \\(k\\) 近邻几何」混进本课；那是后课 k-d 树。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写区间树的重叠查询。并发下 size 与旋转同锁。下一课把<a href="/cs/skip-list">跳表</a> 接到多线程：无根旋转，层指针 CAS。</p><p>后课默认：有序字典可以回答秩。共享内存里无锁有序集，先看并发跳表。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>顺序统计：BST + size，<code>rank</code>/<code>select</code> 对数。</li><li>旋转必须维护 size。</li><li>并发有序结构下一课走跳表，不旋根。</li><li>出处：Cormen et al. 第 14 章；Sedgewick and Wayne。</li></ul>',7))])}const T=E(B,[["render",A]]);export{S as __pageData,T as default};
